{
  "items": [
    {
      "title": "German Longitudinal Election Study (GLES) – Cross-Section 2025, Post-Election",
      "url_or_doi": "https://search.gesis.org/research_data/ZA10100",
      "justification": "A major dataset for studying voting behaviour and political attitudes in Germany following the February 2025 federal election. Contains survey responses from 7,336 individuals, covering electoral choices, political preferences, party evaluations, and political participation. Particularly useful for examining voter behaviour, party support, and political polarization in contemporary Germany."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – 2025 Federal Election Studies",
      "url_or_doi": "https://www.gesis.org/en/gles/2025-federal-election",
      "justification": "A collection of datasets covering the 2025 German federal election, including cross-sectional surveys, rolling cross-sections, longitudinal panels, and candidate studies. Enables researchers to investigate changes in voting intentions, political attitudes, electoral decision-making, and campaign effects. Particularly relevant for studying the rise of new political movements and shifts in party preferences during the 2020s."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Cross-Section 2021",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Provides individual-level survey data collected around the 2021 German federal election. Covers voting decisions, party identification, political attitudes, candidate evaluations, and electoral participation. Useful for analyzing political behaviour during the transition from Angela Merkel's chancellorship and comparing electoral preferences between the 2021 and 2025 federal elections."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Tracking 2009–2026, Cumulation",
      "url_or_doi": "https://search.gesis.org/research_data/ZA6832",
      "justification": "A harmonized longitudinal dataset combining repeated GLES tracking surveys through 2026. Particularly valuable for investigating changes in political attitudes, party preferences, voting intentions, and public opinion across the 2020s. Its repeated measurements facilitate trend analysis of political polarization, electoral volatility, and changing support for German political parties."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Rolling Cross-Section 2025",
      "url_or_doi": "https://www.gesis.org/en/gles/2025-federal-election",
      "justification": "Contains daily survey observations collected before and after the 2025 German federal election. Designed to capture changes in political attitudes and electoral behaviour throughout the election campaign. Especially useful for analyzing campaign dynamics, political events, voter mobilization, and short-term shifts in support for parties."
    },
    {
      "title": "German General Social Survey (ALLBUS) 2023",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "A nationally representative survey examining social attitudes, values, and demographic characteristics in Germany. The 2023 wave includes measures relevant to political trust, democratic attitudes, political participation, and social divisions. Useful for studying the relationship between political beliefs and socioeconomic characteristics, including education, religion, and regional differences."
    },
    {
      "title": "German General Social Survey (ALLBUS) 2025",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "The 2025 wave of Germany's long-running general social survey provides contemporary information on social and political attitudes. Relevant for examining political trust, democratic values, ideological differences, and associations between social characteristics and political preferences. Can be compared with earlier ALLBUS waves to identify political and social changes during the 2020s."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2023",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "A harmonized dataset combining multiple decades of German social survey data, including observations from the 2020s. Particularly suitable for identifying long-term changes in political attitudes, democratic values, institutional trust, and political participation. Enables researchers to compare contemporary political developments with historical patterns and investigate East–West German differences."
    },
    {
      "title": "Politbarometer 2025 – German Political Opinion Survey",
      "url_or_doi": "https://www.gesis.org/en/elections/politbarometer",
      "justification": "A cumulative dataset of regular public opinion surveys conducted by Forschungsgruppe Wahlen for ZDF. Covers political party preferences, evaluations of politicians, voting intentions, and attitudes toward current political issues. Highly relevant for examining public opinion during the 2025 federal election and tracking changing political preferences throughout the year."
    },
    {
      "title": "Politbarometer 1977–2024 – Partial Cumulation",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2391",
      "justification": "A longitudinal compilation of German political opinion surveys spanning several decades, including 2020–2024. Contains measures related to political preferences, party evaluations, voting intentions, and assessments of political developments. Particularly useful for analyzing the evolution of political attitudes during the COVID-19 pandemic, the energy crisis, and changes in Germany's party system."
    },
    {
      "title": "German Internet Panel (GIP) – Longitudinal Survey Data",
      "url_or_doi": "https://paneldata.org/gip/",
      "justification": "A probability-based longitudinal survey conducted by the University of Mannheim that collects information on political and economic attitudes among German residents. Includes survey waves throughout the 2020s, allowing researchers to investigate changes in political preferences, institutional trust, policy attitudes, and responses to political events. Particularly useful for individual-level longitudinal analysis."
    },
    {
      "title": "German Internet Panel – Wave 70 (March 2024)",
      "url_or_doi": "https://doi.org/10.4232/1.14744",
      "justification": "A specific 2024 wave of the German Internet Panel providing individual-level survey data on attitudes and preferences relevant to political and economic decision-making. Useful for examining contemporary political opinions and linking respondents' attitudes to previous and subsequent panel observations. Suitable for studying political opinion formation and changes in policy preferences."
    },
    {
      "title": "German Internet Panel – Wave 48 (July 2020)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA7645",
      "justification": "A German Internet Panel survey wave conducted during the first year of the COVID-19 pandemic. Provides information on individual attitudes and preferences relevant to political and economic decision-making. Particularly valuable as an early-2020s reference point for examining political attitudes during a period of major social and institutional disruption."
    },
    {
      "title": "Mannheim Corona Study (2020) – German Public Attitudes During COVID-19",
      "url_or_doi": "https://www.uni-mannheim.de/en/gip/using-gip-data/",
      "justification": "A longitudinal survey initiative developed using the German Internet Panel infrastructure to investigate social, economic, and behavioural responses to the COVID-19 pandemic. Relevant for studying public responses to government interventions, pandemic-related behaviour, and social consequences of political decisions. Particularly useful for investigating how the pandemic influenced political behaviour and attitudes in Germany."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Panel 2016–2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A longitudinal election study following respondents across multiple survey waves and electoral cycles. Measures voting intentions, political involvement, party preferences, political attitudes, and perceptions of political developments. Particularly useful for examining individual-level political attitude changes, electoral switching, and the development of partisan identification during the 2020s."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – European Parliament Election 2024 Candidate Study",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A dataset examining candidates participating in the 2024 European Parliament elections. Provides a complementary perspective on political behaviour by focusing on political elites rather than voters. Relevant for investigating candidate characteristics, political representation, and electoral competition in Germany within the broader European political context."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Coding of the Most Important Political Problem, 2018–2023",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A dataset providing standardized classifications of the political problems identified as most important by survey respondents. Includes observations from 2020–2023, making it useful for studying the evolution of political issue priorities. Relevant for analyzing public concern about immigration, economic conditions, climate change, government performance, and other politically salient issues."
    },
    {
      "title": "GESIS Election Studies – German Federal and State Elections",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/election-studies",
      "justification": "An official collection of German election research datasets covering federal and state elections, including studies conducted during the 2020s. Provides access to survey-based evidence on voting behaviour, political participation, party preferences, and political attitudes. Particularly useful for comparing political developments across German federal states and identifying regional differences in electoral behaviour."
    },
    {
      "title": "GESIS Election Studies – Politbarometer Monthly Political Opinion Surveys",
      "url_or_doi": "https://www.gesis.org/en/elections/politbarometer",
      "justification": "A comprehensive collection of recurring surveys measuring the German electorate's attitudes toward political parties, politicians, and current political issues. Annual cumulative datasets are available for the 2020s. Particularly valuable for studying short-term fluctuations in public opinion, government approval, political dissatisfaction, and changes in electoral support."
    },
    {
      "title": "German Internet Panel – Survey Waves 2024–2025",
      "url_or_doi": "https://www.uni-mannheim.de/en/gip/",
      "justification": "Recent waves of the University of Mannheim's longitudinal survey, including November 2024, January 2025, and March 2025. The panel investigates political and economic attitudes and preferences over time. Useful for studying changes in political opinions surrounding the 2025 federal election and examining the relationship between political attitudes and socioeconomic conditions."
    }
  ]
}
